### Steps to reproduce

1. Tap `Go to guarded route`.
2. Tap `Push raw route`.
3. Tap `Pop until first`.

### Expected results

`Navigator.popUntil((route) => route.isFirst)` should complete, or at minimum fail with an error message without locking up the UI thread.

### Actual results

The app hangs after this log:

```text
Raw: calling Navigator.popUntil(route.isFirst)
```

This log is never printed:

```text
Raw: this line is never reached when the app freezes
```


### Code sample

<details open><summary>Code sample</summary>

```dart
import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

void main() {
  runApp(const ReproApp());
}

final GoRouter router = GoRouter(
  initialLocation: '/parent',
  debugLogDiagnostics: true,
  routes: [
    GoRoute(
      path: '/parent',
      builder: (context, state) => const ParentPage(),
      routes: [
        GoRoute(
          path: 'guarded',
          onExit: (context, state) {
            debugPrint('guarded onExit: returning true');
            return true;
          },
          builder: (context, state) => const GuardedPage(),
        ),
      ],
    ),
  ],
);

class ReproApp extends StatelessWidget {
  const ReproApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp.router(
      title: 'go_router popUntil onExit repro',
      debugShowCheckedModeBanner: false,
      routerConfig: router,
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.indigo),
        useMaterial3: true,
      ),
    );
  }
}

class ParentPage extends StatelessWidget {
  const ParentPage({super.key});

  @override
  Widget build(BuildContext context) {
    return ReproScaffold(
      title: 'Parent',
      path: '/parent',
      color: const Color(0xffeef7ff),
      body: FilledButton(
        onPressed: () {
          debugPrint('Parent: context.go("/parent/guarded")');
          context.go('/parent/guarded');
        },
        child: const Text('Go to guarded route'),
      ),
    );
  }
}

class GuardedPage extends StatelessWidget {
  const GuardedPage({super.key});

  @override
  Widget build(BuildContext context) {
    return ReproScaffold(
      title: 'Guarded',
      path: '/parent/guarded',
      color: const Color(0xfffff8d8),
      body: FilledButton(
        onPressed: () {
          debugPrint('Guarded: Navigator.push(RawPushedPage)');
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (context) => const RawPushedPage(),
            ),
          );
        },
        child: const Text('Push raw route'),
      ),
    );
  }
}

class RawPushedPage extends StatelessWidget {
  const RawPushedPage({super.key});

  @override
  Widget build(BuildContext context) {
    return ReproScaffold(
      title: 'Raw route',
      path: 'MaterialPageRoute above /parent/guarded',
      color: const Color(0xffe8fff4),
      body: FilledButton(
        onPressed: () {
          debugPrint('Raw: calling Navigator.popUntil(route.isFirst)');
          Navigator.of(context).popUntil((route) => route.isFirst);
          debugPrint('Raw: this line is never reached when the app freezes');
        },
        child: const Text('Pop until first'),
      ),
    );
  }
}

class ReproScaffold extends StatelessWidget {
  const ReproScaffold({
    required this.title,
    required this.path,
    required this.color,
    required this.body,
    super.key,
  });

  final String title;
  final String path;
  final Color color;
  final Widget body;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: color,
      appBar: AppBar(title: Text(title)),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 560),
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(path, style: Theme.of(context).textTheme.headlineSmall),
                  const SizedBox(height: 16),
                  body,
                  const SizedBox(height: 24),
                  Text(
                    'Current go_router URI: ${router.state.uri}',
                    style: Theme.of(context).textTheme.bodySmall,
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

```

</details>


